(* [comment removed for export] *)
Lemma usage_ret_walk : forall (usp : Z) (gp s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 v : word)
    (t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) F fc (m : word -> option byte) (lo : Z)
    (c0 c1 c2 c3 c4 c5 c6 c7 : word) junk,
  stk asegs m lo (usp - 80) -> SEGTOP_A <= lo -> lo + 0x100000 <= usp -> usp mod 16 = 0 -> usp < 2^47 ->
  rw_cells asegs m (usp - 80) [CB 8 junk; C8 c7; C8 c6; C8 c5; C8 c4; C8 c3; C8 c2; C8 c1; C8 c0; C8 (Z_to_bv 64 MAIN_RA)] ->
  mem_inv asegs m ->
  evt asegs (fun ms' => ms' = entry_st (Z_to_bv 64 0xf6bf4) (Z_to_bv 64 usp) gp (Z_to_bv 64 TP_A) t0 t1 t2
                                    c0 c1 (Z_to_bv 64 2) a1 a2 a3 a4 a5 a6 a7
                                    c2 c3 c4 c5 c6 c7 s8 s9 s10 s11 t3 t4 t5 t6 F fc e_exit m
       /\ stk asegs m lo usp)
    (MS (mkR (Z_to_bv 64 0x96228) (Z_to_bv 64 (usp - 80)) gp (Z_to_bv 64 TP_A) t0 t1 t2 (Z_to_bv 64 2) s1 v a1 a2 a3 a4 a5 a6 a7
